import { LineChart, useLineChart } from '@dreadnought/ui/react';
const series=[{id:'a',label:'A',data:[{x:0,y:20},{x:1,y:40}]}];
function Summary() { const {visible}= useLineChart(); return <p>Видимых серий: {visible.length}</p>; }
export function Example() { return <LineChart label="Данные" series={series} xDomain={[0,1]} yDomain={[0,50]}><Summary /><LineChart.Legend>{({defaultContent}) => <span>{defaultContent}</span>}</LineChart.Legend><LineChart.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</LineChart.Plot><LineChart.RangeControls /><LineChart.Table /><LineChart.Pagination /><LineChart.Empty /></LineChart>; }
